{
  "sop_id": "SOP-018",
  "title": "Daily Operations Report",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to self",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Collect production, downtime and manpower data from every site",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Reconcile against the plan and compute the KPIs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Record incidents, deviations and actions taken",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Compile and publish the report",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Review and approval of flagged reports",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and republish on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "KPI breach or safety event flagged"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
